use config::{Config, File};
use serde::Deserialize;
use serde::de::DeserializeOwned;
use sha2::{Digest, Sha256};

#[derive(Debug, Clone, Deserialize)]
pub struct ServerConfig {
    pub host: String,
    pub port: u16,
}

#[derive(Debug, Clone, Deserialize)]
pub struct DatabaseConfig {
    pub url: String,
}

#[derive(Debug, Clone, Deserialize)]
pub struct LoggingConfig {
    pub level: String,
    pub format: String,
}

/// CSP for layouts that load every script from a file (the layout generated by
/// `rwfw new app` since 0.1.0-alpha.7): `script-src 'self'` with no
/// `'unsafe-inline'`, so an injected `<script>` does not run.
pub const STRICT_CONTENT_SECURITY_POLICY: &str = "default-src 'self'; script-src 'self'; \
     style-src 'self' 'unsafe-inline'; img-src 'self' data: https:; \
     font-src 'self' data:; object-src 'none'; base-uri 'self'; \
     frame-ancestors 'self'";

/// Framework default CSP. It still allows inline scripts because layouts
/// generated before 0.1.0-alpha.7 boot Turbo/Stimulus from an inline module;
/// a later release switches the default to [`STRICT_CONTENT_SECURITY_POLICY`].
pub const LEGACY_CONTENT_SECURITY_POLICY: &str = "default-src 'self'; \
     script-src 'self' 'unsafe-inline'; \
     style-src 'self' 'unsafe-inline'; img-src 'self' data: https:; \
     font-src 'self' data:; object-src 'none'; base-uri 'self'; \
     frame-ancestors 'self'";

/// Default `Referrer-Policy` value.
pub const DEFAULT_REFERRER_POLICY: &str = "strict-origin-when-cross-origin";

/// Opt-in web security knobs (response headers + auth rate limiting), read from
/// the `security:` config section. Every field has a safe default so apps that
/// omit the section still get sensible protection (headers on, HSTS/rate-limit
/// off — both are deployment-specific).
///
/// `#[non_exhaustive]`: build it from config or from `Default` and assign
/// fields, so new knobs can be added without breaking callers.
#[derive(Debug, Clone, Deserialize)]
#[serde(default)]
#[non_exhaustive]
pub struct SecurityConfig {
    /// Emit X-Content-Type-Options / X-Frame-Options / Referrer-Policy / CSP.
    pub headers_enabled: bool,
    /// Emit Strict-Transport-Security (only safe behind TLS; default off).
    pub hsts: bool,
    /// Content-Security-Policy value; `None` skips the header.
    pub content_security_policy: Option<String>,
    /// X-Frame-Options value.
    pub frame_options: String,
    /// Referrer-Policy value (default `strict-origin-when-cross-origin`). An
    /// empty string skips the header.
    pub referrer_policy: String,
    pub rate_limit: RateLimitConfig,
}

impl Default for SecurityConfig {
    fn default() -> Self {
        Self {
            headers_enabled: true,
            hsts: false,
            content_security_policy: Some(LEGACY_CONTENT_SECURITY_POLICY.to_string()),
            frame_options: "SAMEORIGIN".to_string(),
            referrer_policy: DEFAULT_REFERRER_POLICY.to_string(),
            rate_limit: RateLimitConfig::default(),
        }
    }
}

impl SecurityConfig {
    /// True when the configured CSP lets inline `<script>` run (a `script-src`
    /// with `'unsafe-inline'`, or no `script-src` and a `default-src` with it).
    pub fn csp_allows_inline_scripts(&self) -> bool {
        let Some(csp) = &self.content_security_policy else {
            return false;
        };
        let directive = |name: &str| {
            csp.split(';').find_map(|d| {
                let mut parts = d.split_whitespace();
                let found = parts.next()?.eq_ignore_ascii_case(name);
                found.then(|| parts.collect::<Vec<_>>())
            })
        };
        directive("script-src")
            .or_else(|| directive("default-src"))
            .is_some_and(|sources| sources.contains(&"'unsafe-inline'"))
    }
}

/// In-memory rate limiting for auth routes. Disabled by default (in-memory state
/// does not survive restarts or scale across processes — opt in per deployment).
#[derive(Debug, Clone, Deserialize)]
#[serde(default)]
pub struct RateLimitConfig {
    pub enabled: bool,
    pub max_requests: u32,
    pub window_secs: u64,
}

impl Default for RateLimitConfig {
    fn default() -> Self {
        Self {
            enabled: false,
            max_requests: 10,
            window_secs: 60,
        }
    }
}

#[derive(Debug, Clone)]
pub struct AppConfig {
    inner: Config,
}

impl AppConfig {
    pub fn load() -> anyhow::Result<Self> {
        dotenvy::dotenv().ok();

        let env = std::env::var("RWFW_ENV").unwrap_or_else(|_| "development".into());

        tracing::info!(environment = %env, "Loading configuration");

        let config = Config::builder()
            .add_source(File::with_name("config/default").required(false))
            .add_source(File::with_name(&format!("config/{env}")).required(false))
            .add_source(config::Environment::with_prefix("RWFW").separator("__"))
            .build()?;

        Ok(Self { inner: config })
    }

    pub fn server(&self) -> anyhow::Result<ServerConfig> {
        Ok(self.inner.get::<ServerConfig>("server")?)
    }

    pub fn database(&self) -> anyhow::Result<DatabaseConfig> {
        Ok(self.inner.get::<DatabaseConfig>("database")?)
    }

    pub fn logging(&self) -> anyhow::Result<LoggingConfig> {
        Ok(self.inner.get::<LoggingConfig>("logging")?)
    }

    pub fn app_title(&self) -> String {
        self.inner
            .get::<String>("app.title")
            .unwrap_or_else(|_| "RWFW".to_string())
    }

    pub fn module_config<T: DeserializeOwned>(&self, module: &str) -> anyhow::Result<T> {
        Ok(self.inner.get::<T>(module)?)
    }

    /// Security knobs from the `security:` section, falling back to defaults
    /// (headers on, HSTS/rate-limit off) when the section is absent or partial.
    pub fn security(&self) -> SecurityConfig {
        self.inner
            .get::<SecurityConfig>("security")
            .unwrap_or_default()
    }

    pub fn is_development(&self) -> bool {
        std::env::var("RWFW_ENV").unwrap_or_else(|_| "development".into()) == "development"
    }

    pub fn is_test(&self) -> bool {
        std::env::var("RWFW_ENV").unwrap_or_else(|_| "development".into()) == "test" || cfg!(test)
    }

    /// Secret key used to sign stateless reactive component tokens.
    ///
    /// In development and tests, a missing `RWFW_SECRET_KEY` derives a stable
    /// per-project key so local counters work out of the box. In production,
    /// callers pass `required = true` only when a reactive component is
    /// registered, preserving boot behavior for apps that never opt in.
    pub fn reactive_secret_key(&self, required: bool) -> anyhow::Result<Option<Vec<u8>>> {
        if let Ok(secret) = self.inner.get::<String>("secret_key")
            && !secret.is_empty()
        {
            return Ok(Some(secret.into_bytes()));
        }

        if self.is_development() || self.is_test() {
            let root = std::env::current_dir()
                .map(|path| path.display().to_string())
                .unwrap_or_else(|_| "rwfw-development".to_string());
            tracing::warn!(
                "RWFW_SECRET_KEY is unset; deriving a development reactive token key from the project path"
            );
            let digest = Sha256::digest(format!("rwfw-reactive:{root}").as_bytes());
            return Ok(Some(digest.to_vec()));
        }

        if required {
            anyhow::bail!(
                "RWFW_SECRET_KEY must be set when reactive components are registered in production"
            );
        }

        Ok(None)
    }

    /// Build a minimal configuration for tests, overriding only the database URL.
    /// Avoids mutating process-global environment variables across parallel tests.
    #[doc(hidden)]
    pub fn for_test(database_url: &str) -> anyhow::Result<Self> {
        let config = Config::builder()
            .set_override("database.url", database_url)?
            .build()?;
        Ok(Self { inner: config })
    }

    /// Build a test config backed by a SQLite file (or `:memory:`). Used by the
    /// SQLite test harness so the suite runs with no external Postgres.
    #[doc(hidden)]
    pub fn for_test_sqlite(path: &str) -> anyhow::Result<Self> {
        let url = if path == ":memory:" {
            "sqlite::memory:".to_string()
        } else {
            crate::db::sqlite_url_from_path(path)
        };
        Self::for_test(&url)
    }

    /// Return a copy with one key overridden (dotted path, e.g.
    /// `security.rate_limit.enabled`). For tests that need a non-default knob
    /// without touching process-global environment variables.
    #[doc(hidden)]
    pub fn with_override<V: Into<config::Value>>(
        self,
        key: &str,
        value: V,
    ) -> anyhow::Result<Self> {
        let config = Config::builder()
            .add_source(self.inner)
            .set_override(key, value)?
            .build()?;
        Ok(Self { inner: config })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn security_from_yaml(yaml: &str) -> SecurityConfig {
        let config = Config::builder()
            .add_source(File::from_str(yaml, config::FileFormat::Yaml))
            .build()
            .unwrap();
        AppConfig { inner: config }.security()
    }

    #[test]
    fn referrer_policy_defaults_when_absent_from_yaml() {
        let security = security_from_yaml("security:\n  hsts: true\n");
        assert!(security.hsts);
        assert_eq!(security.referrer_policy, DEFAULT_REFERRER_POLICY);
    }

    #[test]
    fn referrer_policy_reads_from_yaml() {
        let security = security_from_yaml("security:\n  referrer_policy: \"no-referrer\"\n");
        assert_eq!(security.referrer_policy, "no-referrer");
    }

    #[test]
    fn with_override_keeps_existing_keys() {
        let config = AppConfig::for_test("sqlite::memory:")
            .unwrap()
            .with_override("security.rate_limit.enabled", true)
            .unwrap();
        assert!(config.security().rate_limit.enabled);
        assert_eq!(config.database().unwrap().url, "sqlite::memory:");
    }

    #[test]
    fn detects_inline_scripts_in_csp() {
        let with_csp = |csp: Option<&str>| {
            let mut security = SecurityConfig::default();
            security.content_security_policy = csp.map(str::to_string);
            security.csp_allows_inline_scripts()
        };
        assert!(with_csp(Some(LEGACY_CONTENT_SECURITY_POLICY)));
        assert!(!with_csp(Some(STRICT_CONTENT_SECURITY_POLICY)));
        // style-src 'unsafe-inline' does not count.
        assert!(!with_csp(Some(
            "default-src 'self'; style-src 'self' 'unsafe-inline'"
        )));
        // No script-src: default-src governs scripts.
        assert!(with_csp(Some("default-src 'self' 'unsafe-inline'")));
        assert!(!with_csp(None));
    }
}
